  tc = `Tema Event: %1$s`,
  nc = `Halloween 2022`,
  rc = `Apakah event ini terkait dengan pembaruan game-mu untuk Halloween 2022? Kami ingin tahu jika kamu menambah map, skin, ilustrasi, atau konten lain di game ini untuk Halloween, atau jika kamu mengadakan event dengan konten menyeramkan spesial, tantangan, atau aktivitas lain dalam waktu terbatas. Kami sedang mempertimbangkan cara yang lebih baik untuk memunculkan event bertema untuk audiens yang lebih luas, tapi kami harus tahu kegiatan seperti apa yang pengembang akan selenggarakan di game mereka (jika ada) untuk merayakan Halloween. Centang kotak di bawah ini jika event ini terkait dengan pembaruan di game-mu untuk Halloween 2022.`,
  ic = `Event bertema Halloween`,
  ac = `Kamu sedang mengadakan event atau menambahkan konten bertema Halloween? Lihat %1$s untuk pelajari lebih lanjut tentang cara berpartisipasi di Steam Scream dengan event dalam game-mu yang bertema Halloween.`,
