  $_ = `Tampilkan banner kanan dan kiri alih-alih kapsul game.`,
  ev = `Ketika diaktifkan, kapsul game tidak akan ditampilkan melainkan banner-nya saja. Ini bermanfaat ketika banner memberikan informasi yang lebih berguna tentang event daripada kapsul aplikasi tertentu. Ini juga berguna ketika ada streaming untuk beberapa game dalam jangka waktu tertentu dan kamu hanya ingin memperlihatkan satu aset event.`,
  tv = `Daftar Penyiar yang diizinkan`,
