  cv = `Prioritas`,
  lv = `Apa prioritas untuk siaran ini dibandingkan dengan siaran lain. Siaran akan dipilih berdasarkan tinggi rendahnya prioritas masing-masing siaran. Jika ada beberapa siaran dengan prioritas yang sama maka satu akan dipilih secara acak sebagai default siaran.`,
