  Yv = `Ini adalah kompetisi antara lebih dari dua orang atau dua tim. Setelah pertandingan selesai, kamu bisa memperbarui hasil dan informasi tentang pemenangnya.`,
  Xv = `Siaran`,
  Zv = `Ini adalah panggilan untuk pengguna untuk menonton livestream di Steam atau di tempat lain untuk periode waktu ini.`,
