  ey = `Di Dunia Nyata`,
  ty = `Digunakan ketika bagian dari jadwal akan terjadi dan ketika hanya bisa diakses oleh pengguna di event ini dan ini tidak bisa digunakan untuk siaran langsung. Catatan: Mungkin akan lebih bermanfaat kalau tidak disertakan dalam jadwal karena penggemar Steam-mu tak bisa berpartisipasi.`,
