  ry = `Ditentukan sebagai menit dari saat Event Mulai`,
  iy = `Menit`,
  ay = `Entri dari jadwal ini telah berubah dari default. Kamu yakin mau menghapusnya? Kamu tidak bisa membatalkan tindakan ini`,
  oy = `Trek Saat Ini`,
  sy = `Trek mengikat satu set event yang berhubungan satu sama lain dengan gambar merek dan skema warna yang sama. Event tidak diharuskan muncul di jadwal. Contohnya, Panggung Utama atau Trek Seni.`,
  cy = `Trek belum ditentukan.`,
  ly = `Tambahkan Trek`,
  uy = `Tambahkan trek baru untuk grup dan event merek di jadwal.`,
  dy = `Hapus Trek`,
  fy = `Apa kamu yakin ingin menghapus trek ini?`,
  py = `Trek Tanpa Label %1$s`,
  my = `Tambahkan event khususnya untuk trek ini. Event-event ini hanya valid jika mereka sudah dipublikasikan, serta memiliki waktu mulai dan waktu selesai dalam rentang waktu yang dijadwalkan, dan sesuai dengan jenis event yang diizinkan untuk jadwal ini.`,
  hy = `Perjanjian Event Diskon`,
  gy = `Sebelum kamu bisa menggunakan alat editor diskon, kamu harus menyetujui persyaratan berikut ini:`,
  _y = `Saya mengerti bahwa halaman diskon harus mendeskripsikan grup dan orang yang bertanggungjawab untuk mengorganisasi diskon atau event secara jelas.`,
  vy = `Saya mengerti bahwa saya tidak dapat menjamin peserta untuk mendapatkan tingkat visibilitas tertentu di Steam, dan saya tidak dapat membebankan biaya untuk penempatan di dalam halaman.`,
  yy = `Saya mengerti bahwa Valve berhak untuk mengubah halaman diskon, termasuk tapi tidak terbatas pada visibilitas game atau siaran di halaman, atau teks atau gambar yang menjelaskan tentang event.`,
  by = `Saya mengerti bahwa Valve akan memilih event untuk dipromosikan dalam toko Steam dan kemungkinan event saya bisa tidak dipromosikan.`,
  xy = `Saya mengerti bahwa saya hanya dapat menambahkan game ke halaman diskon yang saya terima perizinannya dari pengembang atau penerbit. Pengembang game akan melihat game mereka disertakan di dalam diskon saya segera setelah ditambahkan ke halaman diskon saya ini.`,
  Sy = `Saya menyetujui semua peraturan sebagaimana diatur dalam %1$s`,
