  Ly = `Silakan sediakan nama dan URL untuk pengelola event ini. Informasi ini akan ditampilkan di bagian atas halaman diskonmu. Informasi ini diperlukan dan bisa diedit kapan saja.`,
  Ry = `Pengelola Event`,
