  By = `Masukkan Info Penyelenggara`,
  Vy = `Silakan masukkan nama entitas pengelola event ini. Tautan dapat mengarahkan ke beranda kreator penyelenggara di Steam ataupun ke URL eksternal. Nama dalam bahasa Inggris diperlukan, tapi dapat dilokalkan (opsional).`,
  Hy = `Informasi ini bisa ditampilkan di halaman diskonmu seperti ini:`,
