  Ky = `Pelokalan Grup Gambar`,
  qy = `Gambar Utama untuk Pelokalan Grup Gambar`,
  Jy = `Ini adalah gambar default yang digunakan bila tidak ada versi yang dilokalkan untuk bahasa yang coba dilihat oleh pengguna. Versi ini bisa ditampilkan tanpa bahasa apa pun di dalamnya atau bisa juga bahasa yang umum digunakan oleh pelangganmu.`,
  Yy = `Jika gambarmu berisi teks, kamu dapat mengunggah versi gambar yang dilokalkan di sini untuk bahasa apa pun yang didukung Steam. Steam akan secara otomatis menampilkan gambar yang dilokalkan kepada pelanggan sesuai dengan lokasi mereka.`,
