  Qy = `Gambar`,
  $y = `Gunakan area di bagian bawah untuk mengunggah gambar baru untuk dapat digunakan di seluruh event yang kamu buat. Kamu dapat seret dan lepas gambar atau klik untuk menyisipkan thumbnail atau gambar dengan ukuran penuh ke postinganmu.`,
