  gx = `Logo`,
  _x = `Kamu bisa menamai file gambar kamu dengan akhiran nama bahasa untuk dikategorikan sebagai bagian dari bahasa itu secara otomatis. (cth."header_french.jpg"). %1$s untuk daftar bahasa yang didukung.`,
