  bx = `Unggah Gambar`,
  xx = `Kelola 1 gambar`,
  Sx = `Kelola %1$s gambar`,
  Cx = `Tambahkan gambar tajuk yang impresif ke halaman rincian untuk mengomunikasikan tema atau tujuan pembaruan atau pengumuman. Perlu diingat bahwa penting untuk mengunduh templat (tautan ada di bagian atas halaman ini) untuk memastikan bahwa gambar tajuk didesain dengan tepat untuk berbagai situasi di mana gambar tersebut digunakan.`,
  wx = `Pratinjau halaman rincianmu:`,
  Tx = `Pratinjau halaman pop-up event-mu:`,
  Ex = `Gambar ini akan muncul di panel samping di sebelah siaranmu.`,
  Dx = `Event dan pengumuman penting bisa menggunakan gambar banner yang ditampilkan di halaman tokomu selama event berlangsung. Ilustrasi untuk banner ini terpisah dari lokasi lainnya di toko. Banner ini harus mendapatkan persetujuan dari Valve. Silakan hubungi kontakmu di Valve sebelum mengunggah.`,
  Ox = `Rencanakan deskripsi pendek tentang event yang mudah diingat di banner sorotan sehingga pemain bisa langsung mengetahui apa yang menarik dari event-mu.`,
  kx = `Kamu bisa menggunakan seluruh ruang gambar dan memasukkan deskripsi milikmu sendiri untuk pembaruan atau event dalam gambar tersebut.`,
  Ax = `Ini adalah versi seluler dari banner Sorotan Toko di atas dan digunakan ketika pengguna melihat banner tersebut menggunakan layar yang kecil.`,
  jx = `Gambar ini akan muncul sebagai latar dari halaman diskonmu. Kamu dapat membuat gambar ini sebagai satu gambar besar, atau membuat pengubinan dengan pola berulang.`,
  Mx = `Konten penting harus ditempatkan dalam area selebar 940 px di tengah gambar. Ilustrasi ini dapat melebar ke samping dan ke bawah sesuai keinginanmu. Kamu mungkin ingin agar bagian samping dan bawah ilustrasinya menyatu ke warna solid di sekitarnya dan menggunakan warna latar yang senada. Diharapkan agar ukuran gambar selalu kurang dari 4 MB.`,
  Nx = `Unduh Semua Templat Halaman Diskon (file .psd)`,
  Px = `Gambar Latar Diskon berfungsi dengan baik jika digabungkan dengan Logo Halaman Diskon yang ditentukan di bawah. Jika digunakan bersama-sama, Logo Halaman Diskon akan muncul di atas gambar latar.`,
  Fx = `Templat`,
  Ix = `Gambar ini akan diletakkan pada latar di bagian atas halamanmu. Jika kamu ingin melokalkan gambar, silakan email file .psd ke kontak Valve-mu.`,
  Lx = `Jika disediakan, banner ini akan muncul di halaman toko semua game yang merupakan bagian dari event diskon ini. Banner akan ditampilkan selama event diskon berlangsung dengan batas waktu dua minggu. Harap ingat, banner ini harus disetujui oleh Valve sebelum digunakan dan tidak dapat berupa animasi.`,
  Rx = `Versi ini hanya akan muncul jika resolusi halamannya mengecil untuk tampilan seluler.`,
  zx = `Kamu juga bisa memperbarui gambar hero di perpustakaanmu dengan menambahkan elemen dari event apa pun (pembaruan, pengumuman, musim baru, dll.). Untuk melakukannya, silakan kunjungi tab "aset grafis" di bagian admin halaman toko.`,
  Bx = `Desain`,
  Vx = `Dimensi`,
  Hx = `Penggunaan`,
  Ux = `Diperlukan`,
  Wx = `Opsional`,
  Gx = `Gambar ini biasanya berisikan ilustrasi dan elemen yang mewakili event-mu, beserta pesan singkat yang ingin kamu sampaikan. Dalam beberapa situasi kontekstual, Steam akan secara otomatis memunculkan judul game-mu dan ikonnya di samping gambar ini. Tapi, kami menyarankan untuk menyertakan logo game-mu di gambar sampul karena gambar ini digunakan saat event-mu dibagikan di media sosial.`,
  Kx = `Ini akan muncul di halaman tokomu di bagian pengumuman baru, di daftar event, dan pengumuman, serta di halaman rincian perpustakaanmu juga. Gambar ini akan digunakan ketika event ini dibagikan di media sosial. Ini akan digunakan sebagai tautan ke event-mu atau pengumuman dan mungkin saja ditampilkan bersamaan dengan game lainnya jadi pastikan gambarnya jelas dan mudah dikenali.`,
  qx = `Gambar ini biasanya berisi ilustrasi dan merek yang mewakili penerbit, pengembang, atau franchise milikmu. Steam akan secara otomatis menyertakan ikon avatarmu di sebelah gambar ini dalam beberapa konteks.`,
  Jx = `Gambar ini akan muncul di tempat-tempat di Steam di mana Beranda Kreator ini ditampilkan dan akan digunakan untuk mewakili event ketika dibagikan di media sosial. Gambar harus jelas dan dapat dikenali.`,
  Yx = `Gambar banner untuk tautan "Terbaik Tahun Ini" di Peringkat Steam`,
  Xx = `Ditempatkan di belakang bagian promosi silang untuk diskon ini, seperti pada halaman Diskon & Event, sebagai pengganti Logo Halaman Diskon. Jika logo ini tidak memerlukan pelokalan, unggah sekali saja dalam bahasa Inggris, dan semua bahasa akan menggunakannya.`,
  Zx = `Logo yang ditampilkan di bagian atas halaman diskonmu di atas gambar latar. Gambar ini harus mencakup logo event-mu, tanggal, dan slogan (jika ada), dengan latar transparan.`,
