  OL = `Biasanya, aplikasi yang ditampilkan secara mencolok di suatu halaman tidak akan mendapatkan perhatian yang sama di bagian selanjutnya, sehingga mencegah aplikasi populer ditampilkan berulang kali. Centang kotak ini untuk menonaktifkan fitur pelacakan ini di bagian ini.`,
