  LL = `Aktifkan pengalihan item diperluas/diringkas`,
  RL = `Tampilkan pengalihan item diperluas/diringkas, jika item di tab aktif memiliki dukungan untuk fungsi ini.`,
  zL = `Buka Langsung Laman Landas Event`,
  BL = `Kalau dicentang, kami ingin pengguna dibawa ke laman landas ketika mengeklik event ini. Jika tidak dicentang maka event akan terbuka sebagai inline dalam peramban yang terhubung. Dalam sebagian besar kasus, ini adalah pengalaman yang ideal untuk pengguna karena mereka tidak harus meninggalkan laman landas diskon.`,
  VL = `Bagaimana kamu ingin konten bagian ini ditampilkan? Pilih opsi preset atau konfigurasikan secara manual.`,
  HL = `<1>Opsi tata letak preset</1> - Pilih salah satu opsi preset untuk konfigurasi cepat untuk bagian ini. Kamu selalu dapat menggunakan pengaturan manual di bawah ini untuk menyetel lebih lanjut atau mengubah tata letak sepenuhnya.`,
