  aR = `Tampilan Kapsul Vertikal Animasi`,
  oR = `Tampilan yang lebih tinggi dan lebih luas yang menampilkan animasi bertransisi dan trailer mini di belakang ilustrasi. Menarik secara visual, tapi akan mengganggu bila memiliki lebih dari satu.`,
