  dR = `Tampilkan tombol Opsi Pembelian`,
  fR = `Ketika dicentang, kami akan mengganti tombol "Masuk Keranjang" dengan tombol yang menunjukkan semua opsi pembelian.`,
  pR = `Bagian Tampilan Dinamis`,
  mR = `Bagian tampilan dinamis berguna ketika digabungkan dengan livestream pengumuman. Hal ini memungkinkan operator untuk menambahkan aplikasi/paket/bundel setelah diskon terlihat dan ditampilkan di tampilan pelanggan tanpa harus memuat ulang halamannya. Kami merekomendasikan untuk menempatkan bagian ini di dekat pemutar siaran. Pastikan hanya menambahkan aplikasi yang terlihat, bila menambahkan aplikasi yang disembunyikan maka akan tertahan oleh halaman toko sehingga aplikasinya tidak akan terlihat oleh pelanggan Steam.`,
  hR = `Sembunyikan jika item terlalu sedikit`,
  gR = `Jika dicentang, bagian ini akan disembunyikan jika tidak ada cukup item untuk mengisi satu baris.`,
  _R = `Sembunyikan event duplikat`,
