  yR = `Bagian Tampilan dinamis digunakan bersamaan dengan livestream pengumuman. Ini direkomendasikan untuk menempatkan bagian ini di dekat pemutar siaran di halaman diskon. Harap selalu lihat jika ada event Steam baru yang ditambahkan ke daftar dan muncul di event Steam agar para pelanggan tidak harus memuat ulang halaman tersebut.`,
  bR = `Hanya mengizinkan satu Aplikasi/Bundel/Paket dan satu bagian tampilan dinamis Berita dan Event`,
  xR = `Fitur tidak didukung di Bagian Pintar ini`,
