  QJ = `Secara manual`,
  $J = `Nama dari nilai aspek ini. Nilai Aspek adalah opsi tersendiri yang bisa diklik oleh pengguna untuk memfilter game yang ditunjukkan di bagian ini. Contohnya, "First-Person".`,
  eY = `Teks opsional untuk ditampilkan di sebelah kanan dari nilai aspek ini. Gunakan ini untuk menyediakan keterangan singkat tentang suatu nilai aspek. Contohnya, "1-2 jam" untuk nilai aspek yang diterapkan untuk game dengan waktu bermain yang pendek.`,
  tY = `Nama dari aspek ini. Aspek adalah sekelompok opsi yang berhubungan yang digunakan untuk memfilter game yang ditampilkan di bagian ini. Contohnya, "Genre".`,
  nY = `Secara otomatis mengisi aspek dan nilai aspek berdasarkan kategori tag toko, seperti "Genre" dan "Visual & Sudut Pandang". Setelah diotomatiskan, kamu bisa mengedit setiap aspek dan nilai aspek secara manual sesuai kebutuhan.`,
  rY = `Hapus nilai aspek yang tidak sesuai dengan item yang ada di bagian ini.`,
  iY = `Berapakah jumlah hasil minimum yang kamu inginkan untuk setiap aspek yang dipilih? Ini akan menyembunyikan ketentuan apa pun dari menu sebelah kiri yang tidak memiliki setidaknya item yang cocok sebanyak ini. Jumlah ini dihitung setelah filter tab apa pun diterapkan. Biasanya sekitar 5 adalah angka yang bagus.`,
  aY = `Tampilkan maksimal opsi sebanyak ini di bawah setiap kategori teratas di menu sebelah kiri. Contohnya, jangan tampilkan genre lebih dari jumlah ini, di aspek bernama "Genre". Biasanya 5 adalah jumlah yang bagus.`,
  oY = `Untuk setiap aspek, urutkan nilai aspek menggunakan metrik ini. Yang terbaik biasanya berdasarkan jumlah kecocokan.`,
  sY = `Urutkan nilai aspek menurut urutan abjad pada setiap aspek.`,
  cY = `Urutkan nilai aspek dalam urutan menurun berdasarkan jumlah item yang sesuai pada setiap aspek. Contohnya, pada aspek "Genre", "RPG" akan muncul sebelum "Strategi" jika ada lebih banyak game RPG dibandingkan game Strategi di bagian ini.`,
  lY = `Jangan urutkan nilai aspek. Nilai aspek akan ditampilkan dalam urutan yang ditentukan di dalam daftar di bawah ini.`,
