  lZ = `Pilih satu file atau lebih untuk diunggah untuk mengimpor teks pelokalan untuk judul dan isi. Kami menggunakan file ekstensi untuk menentukan apakah file ini berjenis XML atau CSV. Untuk XML, kami menggunakan bahasa kode API di akhir nama file sebelum ekstensi untuk memperlihatkan bahasa konten dari file XML. Kamu harus mulai dengan mengekspor CSV atau XML untuk memastikan bahwa kamu menggunakan format yang benar.`,
